FUNCTION_BLOCK FB_Estop_Processor
VAR_INPUT
    Field_Estop_IN : BOOL;
    R1_Estop_IN : BOOL;
    R2_Estop_IN : BOOL;
    R3_Estop_IN : BOOL;
    B1_Estop_IN : BOOL;
    B2_Estop_IN : BOOL;
    B3_Estop_IN : BOOL;
END_VAR
VAR_OUTPUT
    Field_Estop_OUT : BOOL;
    R1_Estop_OUT : BOOL;
    R2_Estop_OUT : BOOL;
    R3_Estop_OUT : BOOL;
    B1_Estop_OUT : BOOL;
    B2_Estop_OUT : BOOL;
    B3_Estop_OUT : BOOL;
END_VAR

VAR
    i : INT;
END_VAR

FOR i := 1 TO 7 DO
    CASE i OF
        1: Field_Estop_OUT := NOT Field_Estop_IN;
        2: R1_Estop_OUT := NOT R1_Estop_IN;
        3: R2_Estop_OUT := NOT R2_Estop_IN;
        4: R3_Estop_OUT := NOT R3_Estop_IN;
        5: B1_Estop_OUT := NOT B1_Estop_IN;
        6: B2_Estop_OUT := NOT B2_Estop_IN;
        7: B3_Estop_OUT := NOT B3_Estop_IN;
    END_CASE;
END_FOR;

END_FUNCTION_BLOCK
